/// A TokenStream produces a sequence of tokens. 
/// Rollback is not supported; if a downstream user requires it,
/// they must implement it themselves.
pub trait TokenStream<L: LexemeSet, TokenSpan> {
    fn eat(&mut self, lexeme: L) -> Option<TokenSpan>;
    fn peek(&mut self) -> Option<(L, TokenSpan)>;
    fn peek_n(&mut self, n: usize) -> Option<(L, TokenSpan)>;
    fn advance(&mut self) -> Option<(L, TokenSpan)>;

    fn text(&self, span: TokenSpan) -> &str;
}

/// An InterningTokenStream produces a set of tokens, where some have been interned in a string pool.
/// Which tokens get interned is specific to the LexemeSet used.
pub trait InterningTokenStream<L: LexemeSet, TokenSpan> {
    fn eat(&mut self, lexeme: L) -> Option<TokenSpan>;
    fn peek(&mut self) -> Option<(L, TokenSpan, StringPoolRef)>;
    fn peek_n(&mut self, n: usize) -> Option<(L, TokenSpan, StringPoolRef)>;
    fn advance(&mut self) -> Option<(L, TokenSpan, StringPoolRef)>;

    fn text(&self, span: TokenSpan) -> &str;
}

#[derive(Debug, Clone, Copy)]
pub(crate) struct RawTokenSpan {
    source_idx: usize,
    left: usize,
    right: usize,    
}

const BUFFER_SIZE: usize = 8;
pub(crate) struct RawTokenStream<'src, T: LexemeSet> {
    cursor: usize,
    scanner: DFAScanner,
    source: &'src [u8],

    buffer: VecDeque<(T, RawTokenSpan)>,
}

impl<'src, T: LexemeSet> RawTokenStream<'src, T> {
    pub fn new(source: &'src [u8]) -> RawTokenStream<'src, T> {
        RawTokenStream {
            cursor: 0,
            scanner: DFAScanner::load_lexeme_set_scanner::<T>(),
            source,

            buffer: VecDeque::new(),
        }
    }

    fn refill_buffer(&mut self) {
        self.refill_buffer_to_size(BUFFER_SIZE);
    }

    fn refill_buffer_to_size(&mut self, size: usize) {
        while self.buffer.len() < size {
            let (lexeme, action, next_cursor) =
                match self.scanner.next_word(self.source, self.cursor) {
                    ScannerResult::EndOfInput
                    | ScannerResult::Failed => break,
                    ScannerResult::Ok(lexeme, action, next_cursor) => {
                        (lexeme, action, next_cursor)
                    }
                };

            if action as u32 == CLexemes::Whitespace.to_id() {
                self.cursor = next_cursor;
                continue;
            }

            let l = T::from_id(action as u32)
                .expect("invalid action (is the scanner compatible?)");
            
            let span = RawTokenSpan {
                source_idx: 0,
                left: self.cursor,
                right: next_cursor,
            };

            self.buffer.push_back((l, span));
            self.cursor = next_cursor;
        }
    }
}

// TODO: optimize this
impl<'a, T: LexemeSet> TokenStream<T, RawTokenSpan> for RawTokenStream<'a, T> {
    fn eat(&mut self, expected_lexeme: T) -> Option<RawTokenSpan> {
        self.refill_buffer();
        let matched = match self.buffer.pop_front() {
            Some((lexeme, span)) if lexeme == expected_lexeme => Some(span),
            _ => None,
        };

        matched
    }

    fn peek(&mut self) -> Option<(T, RawTokenSpan)> {
        self.refill_buffer();
        self.buffer.front().copied()
    }

    fn peek_n(&mut self, n: usize) -> Option<(T, RawTokenSpan)> {
        self.refill_buffer_to_size(n + 1);
        self.buffer.get(n).copied()
    }

    fn advance(&mut self) -> Option<(T, RawTokenSpan)> {
        self.refill_buffer();
        let head = self.buffer.pop_front();
        head
    }

    fn text(&self, span: RawTokenSpan) -> &str {
        let bytes = &self.source[span.left..span.right];
        str::from_utf8(bytes).expect("corrupted token span")
    }
}

pub(crate) struct CTokenStream<S> {
    pub(crate) string_pool: StringPool,
    pub(crate) inner: S
}

// RawCTokenStream is only used for testing (i.e. bypassing preprocessor for unit tests)
pub(crate) type RawCTokenStream<'src> = CTokenStream<RawTokenStream<'src, CLexemes>>;
pub(crate) type PreprocessedCTokenStream = CTokenStream<Preprocessor>;

impl<S> CTokenStream<S> {
    pub(crate) fn new(inner: S) -> Self {
        CTokenStream { string_pool: StringPool::new(), inner }
    }
}

impl<TokenSpan, S> InterningTokenStream<CLexemes, TokenSpan> for CTokenStream<S>
    where S: TokenStream<CLexemes, TokenSpan>,
          TokenSpan: Copy
{
    fn eat(&mut self, lexeme: CLexemes) -> Option<TokenSpan> {
        self.inner.eat(lexeme)
    }

    fn peek(&mut self) -> Option<(CLexemes, TokenSpan, StringPoolRef)> {
        let (lexeme, token) = self.inner.peek()?;
        if lexeme == CLexemes::Identifier {
            let s = self.inner.text(token);
            let s_ref = self.string_pool.intern_string(s);
            Some((lexeme, token, s_ref))
        }
        else {
            Some((lexeme, token, StringPoolRef::invalid()))
        }        
    }

    fn peek_n(&mut self, n: usize) -> Option<(CLexemes, TokenSpan, StringPoolRef)> {
        let (lexeme, token) = self.inner.peek_n(n)?;
        if lexeme == CLexemes::Identifier {
            let s = self.inner.text(token);
            let s_ref = self.string_pool.intern_string(s);
            Some((lexeme, token, s_ref))
        }
        else {
            Some((lexeme, token, StringPoolRef::invalid()))
        } 
    }

    fn advance(&mut self) -> Option<(CLexemes, TokenSpan, StringPoolRef)> {
        let (lexeme, token) = self.inner.advance()?;
        if lexeme == CLexemes::Identifier {
            let s = self.inner.text(token);
            let s_ref = self.string_pool.intern_string(s);
            Some((lexeme, token, s_ref))
        }
        else {
            Some((lexeme, token, StringPoolRef::invalid()))
        }
    }

    fn text(&self, span: TokenSpan) -> &str {
        self.inner.text(span)
    }
}

